<?php $companyAddress=(string)setting('company_address');$companyEmail=(string)setting('company_email');?><!doctype html><html><head><meta charset="utf-8"><title><?= e($invoice['invoice_number']) ?></title><style>body{font-family:DejaVu Sans,Arial,sans-serif;color:#172033;font-size:12px;margin:35px}*{box-sizing:border-box}.head{display:flex;justify-content:space-between;border-bottom:3px solid #0794B5;padding-bottom:18px}.brand{font-size:22px;font-weight:bold;color:#101936}.brand span{color:#0794B5}.meta{display:flex;justify-content:space-between;margin:25px 0}.meta>div{width:45%}h1{font-size:24px;margin:0;color:#101936;text-transform:uppercase}.muted{color:#667085}table{width:100%;border-collapse:collapse;margin-top:22px}th{background:#101936;color:white;text-align:left;padding:10px}td{padding:10px;border-bottom:1px solid #e4e7ec}.right{text-align:right}.totals{width:42%;margin:20px 0 0 auto}.totals div{display:flex;justify-content:space-between;padding:6px}.totals .grand{border-top:2px solid #101936;font-size:16px;font-weight:bold}.pending{color:#dc2626}.paid{color:#15803d}.foot{margin-top:40px;padding-top:15px;border-top:1px solid #e4e7ec;text-align:center;color:#667085}@media print{body{margin:10mm}.no-print{display:none}}</style></head><body><div class="head"><div><div class="brand">Rankers <span>Mind</span></div><?php if($companyAddress!==''||$companyEmail!==''):?><div class="muted"><?= nl2br(e($companyAddress)) ?><?= $companyAddress!==''&&$companyEmail!==''?'<br>':'' ?><?= e($companyEmail) ?></div><?php endif;?></div><div class="right"><h1><?= e($invoice['invoice_type']) ?></h1><strong><?= e($invoice['invoice_number']) ?></strong></div></div><div class="meta"><div><span class="muted">BILL TO</span><h3><?= e($invoice['company_name']) ?></h3><p><?= nl2br(e($invoice['billing_address']?:$invoice['city'].', '.$invoice['state'])) ?><br><?= e($invoice['email']) ?><br><?= e($invoice['gstin']?'GSTIN: '.$invoice['gstin']:'') ?></p></div><div class="right"><p><span class="muted">Invoice date:</span> <?= e(date('d M Y',strtotime($invoice['invoice_date']))) ?><br><span class="muted">Due date:</span> <?= e(date('d M Y',strtotime($invoice['due_date']))) ?><br><span class="muted">Project:</span> <?= e($invoice['project_name']?:'General') ?><br><span class="muted">Status:</span> <strong><?= e($invoice['status']) ?></strong></p></div></div><table><thead><tr><th>Description</th><th class="right">Qty</th><th class="right">Rate</th><th class="right">Tax</th><th class="right">Amount</th></tr></thead><tbody><?php foreach($items as $item):?><tr><td><?= e($item['description']) ?><br><small class="muted"><?= e($item['hsn_sac']?'HSN/SAC '.$item['hsn_sac']:'') ?></small></td><td class="right"><?= e($item['quantity']) ?></td><td class="right"><?= money($item['rate']) ?></td><td class="right"><?= e($item['tax_percent']) ?>%</td><td class="right"><?= money($item['amount']) ?></td></tr><?php endforeach;?></tbody></table><div class="totals"><div><span>Subtotal</span><span><?= money($invoice['subtotal']) ?></span></div><div><span>Tax</span><span><?= money($invoice['tax_total']) ?></span></div><div><span>Additional</span><span><?= money($invoice['additional_charges']) ?></span></div><div class="grand"><span>Grand total</span><span><?= money($invoice['grand_total']) ?></span></div><div class="paid"><span>Paid</span><span><?= money($invoice['paid_amount']) ?></span></div><div class="pending"><span>Pending</span><span><?= money($invoice['pending_amount']) ?></span></div></div><div><h4>Notes & terms</h4><p><?= nl2br(e($invoice['notes'])) ?></p><p class="muted"><?= nl2br(e($invoice['terms'])) ?></p></div><div class="foot">This is a computer-generated invoice from Rankers Mind CRM.</div><script>if(!new URLSearchParams(location.search).has('format'))window.print()</script></body></html>
